// ISC 12 Mathematics ch05 Continuity and Differentiability — practice bank with independent re-solve checks.
// Continuity constants are checked with one-sided limits evaluated numerically; discontinuities are classified
// from the numeric one-sided limits and the value; one-sided derivatives with one-sided difference quotients;
// every derivative key (MCQ options, model answers, values) against a central-difference derivative of the
// original function at sample points. ISC scope: implicit, parametric, logarithmic and second-order
// differentiation belong to ch06 (Methods of Differentiation) and appear nowhere here. Set-ups are SOYL's own (D-036)
// and none repeats the CBSE 12 ch05 bank.
import { Q, mk, r } from '../../isc-12-mathematics-ch01/src/lib.mjs';

// ---------------------------------------------------------------- numeric calculus helpers
export const D = (g, x, h = 1e-5) => (g(x + h) - g(x - h)) / (2 * h);
export const close = (a, b, tol = 1e-5) => Math.abs(a - b) <= tol * Math.max(1, Math.abs(b));
export const sameD = (g, dg, xs) => xs.every((x) => close(D(g, x), dg(x)));
export const lim = (g, a, side) => g(a + side * 1e-7);
export const LHD = (g, a, h = 1e-7) => (g(a) - g(a - h)) / h;
export const RHD = (g, a, h = 1e-7) => (g(a + h) - g(a)) / h;
export const isCont = (g, a, fa) => close(lim(g, a, -1), fa, 1e-4) && close(lim(g, a, 1), fa, 1e-4);
/** 'continuous' | 'removable' | 'jump' | 'infinite' from numeric one-sided limits (fa = value, NaN if undefined). */
export function kind(g, a, fa) {
  const L = [1e-4, 1e-6].map((h) => g(a - h)), R = [1e-4, 1e-6].map((h) => g(a + h));
  if (Math.abs(L[1]) > 1e5 || Math.abs(R[1]) > 1e5) return 'infinite';
  if (!close(L[1], R[1], 1e-4)) return 'jump';
  return Number.isFinite(fa) && close(L[1], fa, 1e-4) ? 'continuous' : 'removable';
}
const pickD = (g, opts, xs) => opts.map(([, dg]) => sameD(g, dg, xs));
const L = Math.log, E = Math.exp, S = Math.sin, Co = Math.cos, T = Math.tan, sq = Math.sqrt, As = Math.asin, Ac = Math.acos, At = Math.atan;
const fl = Math.floor, ab = Math.abs;
const sec = (x) => 1 / Co(x);

// =============================================================== MCQ — t01 continuity
Q('m01', mk.mcq({ stem: r`Using one-sided limits, a function $f$ defined on an open interval around $a$ is continuous at $x = a$ exactly when`, opts: [r`$\lim_{x \to a^-} f(x) = \lim_{x \to a^+} f(x) = f(a)$`, r`$\lim_{x \to a^-} f(x) = \lim_{x \to a^+} f(x)$, whatever the value $f(a)$`, r`$f(a)$ is defined`, r`$\lim_{x \to a^-} f(x) = f(a)$ only`], key: 'a', sol: r`All three numbers must exist and agree. Equal one-sided limits alone allow a hole or a misplaced point; a defined value alone allows a jump; the left-hand limit alone ignores the right side.`, d: 1, c: 'recall', t: [1], time: 40 }), (C) => C.key('a'));

Q('m02', mk.mcq({ stem: r`A rule is pieced together as $f(x) = \begin{cases} kx^2 + 1, & x \le 3 \\ 4x - 2, & x > 3 \end{cases}$. For the two pieces to meet without a break at $x = 3$, the constant $k$ must be`, opts: ['$1$', '$9$', r`$\dfrac{10}{9}$`, '$3$'], key: 'a', sol: r`Left-hand limit and value: $9k + 1$. Right-hand limit: $12 - 2 = 10$. So $9k + 1 = 10$ and $k = 1$.`, d: 2, c: 'application', t: [1], time: 60 }), (C) => C.which([1, 9, 10 / 9, 3].map((k) => isCont((x) => (x <= 3 ? k * x * x + 1 : 4 * x - 2), 3, 9 * k + 1)), true));

Q('m03', mk.mcq({ stem: r`Two functions $f$ and $g$ are both continuous at $x = a$. Which conclusion about combining them is always valid?`, opts: [r`$\dfrac{f}{g}$ is continuous at $a$ provided $g(a) \ne 0$`, r`$\dfrac{f}{g}$ is continuous at $a$ even if $g(a) = 0$`, r`$f + g$ may fail to be continuous at $a$`, r`$fg$ is continuous at $a$ only when $f(a) = g(a)$`], key: 'a', sol: r`Sums, differences, products and constant multiples of continuous functions are continuous; a quotient is continuous wherever the denominator is not zero. At a zero of $g$ the quotient is not even defined.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { const f = (x) => x * x + 1, g = (x) => x - 2; C.assert(isCont((x) => f(x) / g(x), 0.5, f(0.5) / g(0.5)) && !Number.isFinite(f(2) / g(2) * 0 + 1 / 0 * 0), 'quotient fine away from the zero of g'); C.key('a'); });

Q('m04', mk.mcq({ stem: r`Counting carefully, at how many points of the open interval $(-2, 2)$ is the sum $h(x) = [x] + |x|$ discontinuous? Here $[x]$ is the greatest integer not exceeding $x$.`, opts: ['$1$', '$2$', '$3$', '$4$'], key: 'c', sol: r`$|x|$ is continuous everywhere, so $h$ is discontinuous exactly where $[x]$ jumps: at the integers $-1$, $0$ and $1$ inside the interval. That is $3$ points.`, d: 3, c: 'analysis', t: [1, 2], time: 75 }), (C) => { const h = (x) => fl(x) + ab(x); let n = 0; for (let k = -199; k < 200; k++) { const a = k / 100; if (kind(h, a, h(a)) !== 'continuous') n++; } C.which([1, 2, 3, 4], n); });

Q('m05', mk.mcq({ stem: r`The quotient $f(x) = \dfrac{x^2 - 7x + 10}{x - 5}$ is undefined at $x = 5$. Which value assigned to $f(5)$ makes $f$ continuous there?`, opts: ['$3$', '$5$', '$-3$', '$0$'], key: 'a', sol: r`For $x \ne 5$, $\dfrac{(x - 2)(x - 5)}{x - 5} = x - 2 \to 3$. Assigning $f(5) = 3$ fills the gap.`, d: 2, c: 'understanding', t: [1, 2], time: 60 }), (C) => { const g = (x) => (x * x - 7 * x + 10) / (x - 5); C.which([3, 5, -3, 0].map((v) => kind(g, 5, v) === 'continuous'), true); });

Q('m06', mk.mcq({ stem: r`Near the origin a function is given by $g(x) = \dfrac{\sin 3x}{\tan 2x}$ for $x \ne 0$. What must $g(0)$ be for $g$ to be continuous at $0$?`, opts: [r`$\dfrac{3}{2}$`, r`$\dfrac{2}{3}$`, '$1$', '$6$'], key: 'a', sol: r`Write $\dfrac{\sin 3x}{\tan 2x} = \dfrac{\sin 3x}{3x} \cdot \dfrac{2x}{\tan 2x} \cdot \dfrac{3}{2} \to 1 \cdot 1 \cdot \dfrac{3}{2}$. So $g(0) = \dfrac{3}{2}$.`, d: 3, c: 'application', t: [1], time: 75 }), (C) => { const g = (x) => S(3 * x) / T(2 * x); C.which([3 / 2, 2 / 3, 1, 6].map((v) => kind(g, 0, v) === 'continuous'), true); });

// =============================================================== MCQ — t02 discontinuity
Q('m07', mk.mcq({ stem: r`A function has a **removable** discontinuity at $x = a$ when`, opts: [r`$\lim_{x \to a} f(x)$ exists, but $f(a)$ is undefined or differs from the limit`, r`the left-hand and right-hand limits at $a$ are finite but unequal`, r`$f(x)$ grows without bound as $x \to a$`, r`$f$ is continuous at $a$ but not differentiable there`], key: 'a', sol: r`"Removable" means the limit exists, so redefining one value fixes the break. Unequal finite one-sided limits give a jump; unbounded values give an infinite discontinuity; a corner is not a discontinuity at all.`, d: 1, c: 'recall', t: [2], time: 45 }), (C) => C.key('a'));

Q('m08', mk.mcq({ stem: r`An imagined data logger records $g(x) = \dfrac{x^2 - 16}{x - 4}$ for $x \ne 4$ but stores $g(4) = 5$ by mistake. At $x = 4$ the function $g$ has`, opts: ['a removable discontinuity', 'a jump discontinuity', 'an infinite discontinuity', 'no discontinuity'], key: 'a', sol: r`For $x \ne 4$, $g(x) = x + 4 \to 8$ from both sides, but $g(4) = 5 \ne 8$. The limit exists, so the discontinuity is removable: set $g(4) = 8$.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { const g = (x) => (x === 4 ? 5 : (x * x - 16) / (x - 4)); C.which(['removable', 'jump', 'infinite', 'continuous'], kind(g, 4, 5)); });

Q('m09', mk.mcq({ stem: r`Describe the behaviour at $x = 1$ of the sign-type function $h(x) = \dfrac{|x - 1|}{x - 1}$ ($x \ne 1$), $h(1) = 1$.`, opts: ['a jump: left-hand limit $-1$, right-hand limit $1$', 'a removable discontinuity with limit $1$', 'an infinite discontinuity', 'continuous, since $h(1) = 1$'], key: 'a', sol: r`For $x < 1$ the quotient is $-1$; for $x > 1$ it is $1$. Finite but unequal one-sided limits mean a jump, which no choice of $h(1)$ can remove.`, d: 2, c: 'analysis', t: [2], time: 60 }), (C) => { const h = (x) => (x === 1 ? 1 : ab(x - 1) / (x - 1)); C.assert(lim(h, 1, -1) === -1 && lim(h, 1, 1) === 1, 'limits -1 and 1'); C.which(['jump', 'removable', 'infinite', 'continuous'], kind(h, 1, 1)); });

Q('m10', mk.mcq({ stem: r`On a graph of $p(x) = \dfrac{1}{(x + 2)^2}$, what kind of break appears at $x = -2$?`, opts: ['an infinite discontinuity', 'a removable discontinuity', 'a jump discontinuity', 'no break; $p$ is continuous there'], key: 'a', sol: r`As $x \to -2$ from either side, $(x + 2)^2 \to 0^+$, so $p(x) \to +\infty$. No finite limit exists: an infinite discontinuity, which cannot be removed.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => { const p = (x) => 1 / (x + 2) ** 2; C.which(['infinite', 'removable', 'jump', 'continuous'], kind(p, -2, NaN)); });

Q('m11', mk.mcq({ stem: r`The cubic quotient $q(x) = \dfrac{x^3 - 27}{x - 3}$ is not defined at $3$. To remove this discontinuity, $q(3)$ should be defined as`, opts: ['$27$', '$9$', '$3$', '$0$'], key: 'a', sol: r`$x^3 - 27 = (x - 3)(x^2 + 3x + 9)$, so for $x \ne 3$, $q(x) = x^2 + 3x + 9 \to 9 + 9 + 9 = 27$.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { const q = (x) => (x ** 3 - 27) / (x - 3); C.which([27, 9, 3, 0].map((v) => kind(q, 3, v) === 'continuous'), true); });

// =============================================================== MCQ — t03 differentiability
Q('m12', mk.mcq({ stem: r`Which implication between differentiability and continuity at a point $c$ holds for every real function?`, opts: ['Differentiable at $c$ implies continuous at $c$.', 'Continuous at $c$ implies differentiable at $c$.', 'Not differentiable at $c$ implies not continuous at $c$.', 'Continuous at $c$ implies the graph is smooth at $c$.'], key: 'a', sol: r`$f(c + h) - f(c) = \dfrac{f(c + h) - f(c)}{h} \cdot h \to f'(c) \cdot 0 = 0$, so differentiability forces continuity. $|x|$ at $0$ shows the converse is false.`, d: 1, c: 'recall', t: [3], time: 45 }), (C) => { C.assert(isCont(ab, 0, 0) && !close(LHD(ab, 0), RHD(ab, 0)), '|x| counterexample'); C.key('a'); });

Q('m13', mk.mcq({ stem: r`A V-shaped graph is given by $g(x) = |2x + 5|$. At its tip $x = -\dfrac{5}{2}$, the function is`, opts: ['continuous but not differentiable', 'differentiable but not continuous', 'continuous and differentiable', 'neither continuous nor differentiable'], key: 'a', sol: r`Both one-sided limits are $0 = g\left(-\dfrac52\right)$. The slope is $-2$ on the left and $2$ on the right, so there is a corner and no derivative.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { const g = (x) => ab(2 * x + 5); C.assert(isCont(g, -2.5, 0) && close(LHD(g, -2.5), -2, 1e-4) && close(RHD(g, -2.5), 2, 1e-4), 'corner -2, 2'); C.key('a'); });

const o14 = [[r`$x^2|x|$`, (x) => x * x * ab(x)], [r`$|x|$`, ab], [r`$|\sin x|$`, (x) => ab(S(x))], [r`$x + |x|$`, (x) => x + ab(x)]];
Q('m14', mk.mcq({ stem: r`Only one of these functions has a derivative at $x = 0$. Which one?`, opts: o14.map((o) => o[0]), key: 'a', sol: r`For $x^2|x|$ both one-sided derivatives are $\lim \dfrac{h^2|h|}{h} = \lim h|h| = 0$. The other three have one-sided slopes $\mp 1$, $\mp 1$ and $0$, $2$ at the origin: corners.`, d: 3, c: 'analysis', t: [3], time: 75 }), (C) => C.which(o14.map(([, g]) => close(LHD(g, 0), RHD(g, 0), 1e-4)), true));

Q('m15', mk.mcq({ stem: r`For the greatest integer function $f(x) = [x]$, what can be said at $x = 2$?`, opts: ['neither continuous nor differentiable', 'continuous but not differentiable', 'differentiable but not continuous', 'continuous and differentiable'], key: 'a', sol: r`Left-hand limit $1$, right-hand limit $2$: a jump, so $f$ is not continuous at $2$; a function that is not continuous cannot be differentiable.`, d: 2, c: 'understanding', t: [2, 3], time: 45 }), (C) => { C.assert(kind(fl, 2, 2) === 'jump', 'jump'); C.key('a'); });

Q('m16', mk.mcq({ stem: r`The pieces $f(x) = \begin{cases} x^2 + a, & x \le 1 \\ bx, & x > 1 \end{cases}$ are to join smoothly, with no break and no corner, at $x = 1$. The pair $(a, b)$ is`, opts: ['$(1, 2)$', '$(2, 1)$', '$(0, 1)$', '$(1, 1)$'], key: 'a', sol: r`No break: $1 + a = b$. No corner: left slope $2x = 2$ equals right slope $b$, so $b = 2$ and $a = 1$.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { const ok = ([a, b]) => { const g = (x) => (x <= 1 ? x * x + a : b * x); return isCont(g, 1, 1 + a) && close(LHD(g, 1), RHD(g, 1), 1e-4); }; C.which([[1, 2], [2, 1], [0, 1], [1, 1]].map(ok), true); });

// =============================================================== MCQ — t04 standard derivatives and chain rule
const o17 = [[r`$(2x + 3)e^{x^2 + 3x}$`, (x) => (2 * x + 3) * E(x * x + 3 * x)], [r`$e^{x^2 + 3x}$`, (x) => E(x * x + 3 * x)], [r`$(x^2 + 3x)e^{x^2 + 3x - 1}$`, (x) => (x * x + 3 * x) * E(x * x + 3 * x - 1)], [r`$(2x + 3)e^{2x + 3}$`, (x) => (2 * x + 3) * E(2 * x + 3)]];
Q('m17', mk.mcq({ stem: r`An exponential growth factor is $e^{x^2 + 3x}$. Its derivative with respect to $x$ is`, opts: o17.map((o) => o[0]), key: 'a', sol: r`The exponential keeps its form and is multiplied by the derivative of the exponent, $2x + 3$. The power rule never applies to $e^{u}$.`, d: 2, c: 'understanding', t: [4], time: 45 }), (C) => C.which(pickD((x) => E(x * x + 3 * x), o17, [-1, 0.2, 0.6]), true));

const o18 = [[r`$-\tan x$`, (x) => -T(x)], [r`$\tan x$`, T], [r`$\dfrac{1}{\cos x}$`, sec], [r`$-\cot x$`, (x) => -1 / T(x)]];
Q('m18', mk.mcq({ stem: r`For $0 < x < \dfrac{\pi}{2}$, the logarithm of the cosine, $\log(\cos x)$, has derivative`, opts: o18.map((o) => o[0]), key: 'a', sol: r`$\dfrac{1}{\cos x} \cdot (-\sin x) = -\tan x$: derivative of the inside over the inside.`, d: 2, c: 'understanding', t: [4], time: 45 }), (C) => C.which(pickD((x) => L(Co(x)), o18, [0.3, 0.8, 1.2]), true));

const o19 = [[r`$5^x \log 5$`, (x) => 5 ** x * L(5)], [r`$x \cdot 5^{x - 1}$`, (x) => x * 5 ** (x - 1)], [r`$5^x$`, (x) => 5 ** x], [r`$\dfrac{5^x}{\log 5}$`, (x) => 5 ** x / L(5)]];
Q('m19', mk.mcq({ stem: r`A quantity grows as $5^x$ with a fixed base. Its rate of change with respect to $x$ is`, opts: o19.map((o) => o[0]), key: 'a', sol: r`$5^x = e^{x\log 5}$, so its derivative is $e^{x\log 5} \cdot \log 5 = 5^x\log 5$. The power-rule answer treats the exponent as a constant.`, d: 2, c: 'understanding', t: [4], time: 45 }), (C) => C.which(pickD((x) => 5 ** x, o19, [-0.5, 0.4, 1.1]), true));

const o20 = [[r`$6\sec^2 3x\tan 3x$`, (x) => 6 * sec(3 * x) ** 2 * T(3 * x)], [r`$2\sec^2 3x\tan 3x$`, (x) => 2 * sec(3 * x) ** 2 * T(3 * x)], [r`$6\sec 3x\tan 3x$`, (x) => 6 * sec(3 * x) * T(3 * x)], [r`$3\sec^2 3x$`, (x) => 3 * sec(3 * x) ** 2]];
Q('m20', mk.mcq({ stem: r`Three layers sit inside $\sec^2 3x$: a square, a secant and $3x$. Its derivative is`, opts: o20.map((o) => o[0]), key: 'a', sol: r`$2\sec 3x \cdot (\sec 3x\tan 3x) \cdot 3 = 6\sec^2 3x\tan 3x$. Dropping the inner factor $3$ gives the second option.`, d: 3, c: 'application', t: [4], time: 75 }), (C) => C.which(pickD((x) => sec(3 * x) ** 2, o20, [0.1, 0.25, 0.4]), true));

Q('m21', mk.mcq({ stem: r`The composite $\sin(\log x)$, $x > 0$, is differentiated and the result is evaluated at $x = 1$. The value is`, opts: ['$1$', '$0$', '$e$', r`$\cos 1$`], key: 'a', sol: r`$\dfrac{d}{dx}\sin(\log x) = \cos(\log x) \cdot \dfrac{1}{x}$. At $x = 1$: $\cos 0 \cdot 1 = 1$.`, d: 2, c: 'application', t: [4], time: 60 }), (C) => C.which([1, 0, Math.E, Co(1)].map((v) => close(v, D((x) => S(L(x)), 1))), true));

// =============================================================== MCQ — t05 inverse trigonometric functions
const o22 = [[r`$-\dfrac{1}{1 + x^2}$`, (x) => -1 / (1 + x * x)], [r`$\dfrac{1}{1 + x^2}$`, (x) => 1 / (1 + x * x)], [r`$-\dfrac{1}{\sqrt{1 - x^2}}$`, (x) => -1 / sq(1 - x * x)], [r`$-\dfrac{1}{1 - x^2}$`, (x) => -1 / (1 - x * x)]];
const acot = (x) => Math.PI / 2 - At(x);
Q('m22', mk.mcq({ stem: r`The inverse cotangent, $\cot^{-1} x$, is a decreasing function on $\mathbb{R}$. Its derivative is`, opts: o22.map((o) => o[0]), key: 'a', sol: r`$\cot^{-1} x = \dfrac{\pi}{2} - \tan^{-1} x$, so its derivative is $-\dfrac{1}{1 + x^2}$, negative as a decreasing function requires.`, d: 2, c: 'understanding', t: [5], time: 45 }), (C) => C.which(pickD(acot, o22, [-0.6, 0.2, 0.7]), true));

const asec = (x) => Ac(1 / x);
const o23 = [[r`$\dfrac{1}{x\sqrt{x^2 - 1}}$`, (x) => 1 / (x * sq(x * x - 1))], [r`$-\dfrac{1}{x\sqrt{x^2 - 1}}$`, (x) => -1 / (x * sq(x * x - 1))], [r`$\dfrac{1}{\sqrt{x^2 - 1}}$`, (x) => 1 / sq(x * x - 1)], [r`$\dfrac{x}{\sqrt{x^2 - 1}}$`, (x) => x / sq(x * x - 1)]];
Q('m23', mk.mcq({ stem: r`On the interval $x > 1$, which expression is the derivative of the inverse secant $\sec^{-1} x$?`, opts: o23.map((o) => o[0]), key: 'a', sol: r`$\sec^{-1} x = \cos^{-1}\dfrac{1}{x}$, whose derivative is $-\dfrac{1}{\sqrt{1 - \frac{1}{x^2}}} \cdot \left(-\dfrac{1}{x^2}\right) = \dfrac{1}{x\sqrt{x^2 - 1}}$ for $x > 1$.`, d: 3, c: 'application', t: [5], time: 75 }), (C) => C.which(pickD(asec, o23, [1.3, 2, 3.5]), true));

const o24 = [[r`$\dfrac{2}{1 + x^2}$`, (x) => 2 / (1 + x * x)], [r`$\dfrac{1}{1 + x^2}$`, (x) => 1 / (1 + x * x)], [r`$\dfrac{2}{1 - x^2}$`, (x) => 2 / (1 - x * x)], [r`$-\dfrac{2}{1 + x^2}$`, (x) => -2 / (1 + x * x)]];
Q('m24', mk.mcq({ stem: r`Using the substitution $x = \tan\theta$, the derivative of $\tan^{-1}\left(\dfrac{2x}{1 - x^2}\right)$ on $-1 < x < 1$ simplifies to`, opts: o24.map((o) => o[0]), key: 'a', sol: r`$\dfrac{2\tan\theta}{1 - \tan^2\theta} = \tan 2\theta$ with $-\dfrac{\pi}{2} < 2\theta < \dfrac{\pi}{2}$, so the function is $2\theta = 2\tan^{-1} x$, with derivative $\dfrac{2}{1 + x^2}$.`, d: 3, c: 'application', t: [5], time: 75 }), (C) => C.which(pickD((x) => At((2 * x) / (1 - x * x)), o24, [-0.6, 0.1, 0.8]), true));

const o25 = [[r`$\dfrac{3}{\sqrt{1 - x^2}}$`, (x) => 3 / sq(1 - x * x)], [r`$\dfrac{1}{\sqrt{1 - x^2}}$`, (x) => 1 / sq(1 - x * x)], [r`$\dfrac{3 - 12x^2}{\sqrt{1 - x^2}}$`, (x) => (3 - 12 * x * x) / sq(1 - x * x)], [r`$-\dfrac{3}{\sqrt{1 - x^2}}$`, (x) => -3 / sq(1 - x * x)]];
Q('m25', mk.mcq({ stem: r`With $x = \sin\theta$ and $-\dfrac12 < x < \dfrac12$, the function $\sin^{-1}(3x - 4x^3)$ reduces to a multiple of $\sin^{-1} x$. Its derivative is`, opts: o25.map((o) => o[0]), key: 'a', sol: r`$3\sin\theta - 4\sin^3\theta = \sin 3\theta$, and $-\dfrac{\pi}{2} < 3\theta < \dfrac{\pi}{2}$ here, so the function is $3\sin^{-1} x$ with derivative $\dfrac{3}{\sqrt{1 - x^2}}$.`, d: 3, c: 'analysis', t: [5], time: 90 }), (C) => C.which(pickD((x) => As(3 * x - 4 * x ** 3), o25, [-0.4, 0.1, 0.45]), true));

const o26 = [[r`$-\dfrac{e^x}{\sqrt{1 - e^{2x}}}$`, (x) => -E(x) / sq(1 - E(2 * x))], [r`$\dfrac{e^x}{\sqrt{1 - e^{2x}}}$`, (x) => E(x) / sq(1 - E(2 * x))], [r`$-\dfrac{1}{\sqrt{1 - e^{2x}}}$`, (x) => -1 / sq(1 - E(2 * x))], [r`$-\dfrac{e^x}{1 + e^{2x}}$`, (x) => -E(x) / (1 + E(2 * x))]];
Q('m26', mk.mcq({ stem: r`For negative $x$, the angle $\cos^{-1}(e^x)$ is differentiated with the chain rule. The result is`, opts: o26.map((o) => o[0]), key: 'a', sol: r`$-\dfrac{1}{\sqrt{1 - (e^x)^2}} \cdot e^x$. For $x < 0$, $0 < e^x < 1$, so the root is real.`, d: 2, c: 'application', t: [5], time: 60 }), (C) => C.which(pickD((x) => Ac(E(x)), o26, [-2, -0.7, -0.2]), true));

// =============================================================== assertion-reason
Q('ar1', mk.ar({ a: r`The greatest integer function has a removable discontinuity at $x = 1$.`, r: r`Just to the left of $x = 1$ the function $[x]$ equals $0$, and at and just to the right of $x = 1$ it equals $1$.`, key: 'd', sol: r`R is true, and it shows the one-sided limits $0$ and $1$ differ: a jump, which cannot be removed by redefining one value. So A is false.`, d: 2, c: 'analysis', t: [2] }), (C) => { C.assert(lim(fl, 1, -1) === 0 && lim(fl, 1, 1) === 1 && kind(fl, 1, 1) === 'jump', 'jump at 1'); C.key('d'); });

Q('ar2', mk.ar({ a: r`$g(x) = \dfrac{x^2 - 1}{x - 1}$ has a removable discontinuity at $x = 1$.`, r: r`$\lim_{x \to 1} g(x)$ exists, but $g(1)$ is not defined.`, key: 'a', sol: r`For $x \ne 1$, $g(x) = x + 1 \to 2$, while $g(1)$ is undefined. That is exactly what "removable" means (define $g(1) = 2$), so R explains A.`, d: 2, c: 'analysis', t: [2] }), (C) => { const g = (x) => (x * x - 1) / (x - 1); C.assert(kind(g, 1, g(1)) === 'removable' && close(lim(g, 1, 1), 2, 1e-4), 'removable, limit 2'); C.key('a'); });

Q('ar3', mk.ar({ a: r`The function $f(x) = |x - 4|$ is continuous at $x = 4$.`, r: r`Every function that is continuous at a point is differentiable at that point.`, key: 'c', sol: r`A is true: both one-sided limits are $0 = f(4)$. R is false: $|x - 4|$ itself is continuous at $4$ but has slopes $-1$ and $1$ there.`, d: 2, c: 'analysis', t: [1, 3] }), (C) => { const f = (x) => ab(x - 4); C.assert(isCont(f, 4, 0) && !close(LHD(f, 4), RHD(f, 4), 1e-4), 'A true, R false'); C.key('c'); });

Q('ar4', mk.ar({ a: r`For $-1 < x < 1$, $\dfrac{d}{dx}\tan^{-1}\left(\dfrac{2x}{1 - x^2}\right) = \dfrac{2}{1 + x^2}$.`, r: r`With $x = \tan\theta$, $\dfrac{2x}{1 - x^2} = \tan 2\theta$, and $-\dfrac{\pi}{2} < 2\theta < \dfrac{\pi}{2}$ when $-1 < x < 1$.`, key: 'a', sol: r`By R the function equals $2\theta = 2\tan^{-1} x$ on this interval, whose derivative is $\dfrac{2}{1 + x^2}$. Both true; R explains A.`, d: 3, c: 'analysis', t: [5] }), (C) => { C.assert(sameD((x) => At((2 * x) / (1 - x * x)), (x) => 2 / (1 + x * x), [-0.7, 0, 0.5]), 'derivative'); C.key('a'); });

Q('ar5', mk.ar({ a: r`The function $e^x + \sin x$ is continuous at every real number.`, r: r`The sum of two functions that are continuous on $\mathbb{R}$ is continuous on $\mathbb{R}$.`, key: 'a', sol: r`$e^x$ and $\sin x$ are continuous everywhere, and R (the algebra of continuous functions) gives A directly.`, d: 1, c: 'understanding', t: [1] }), (C) => { const g = (x) => E(x) + S(x); C.assert([-3, 0, 2.2].every((a) => isCont(g, a, g(a))), 'continuous'); C.key('a'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: r`If $f$ is continuous at $a$ and $g$ is **not** continuous at $a$, then $f + g$ is not continuous at $a$.`, key: 't', sol: r`True. If $f + g$ were continuous at $a$, then $g = (f + g) - f$ would be a difference of continuous functions and hence continuous, a contradiction.`, d: 3, c: 'analysis', t: [1] }), (C) => { const h = (x) => x * x + fl(x); C.assert(kind(h, 1, h(1)) === 'jump', 'example: x^2 + [x] breaks at 1'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`A function that fails to be differentiable at a point cannot be continuous at that point.`, key: 'f', sol: r`False. $|x|$ is continuous at $0$ but has a corner there, so it is not differentiable. Only the reverse implication holds.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(isCont(ab, 0, 0) && !close(LHD(ab, 0), RHD(ab, 0)), 'counterexample'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`On $-1 < x < 1$, the sum $\sin^{-1} x + \cos^{-1} x$ has derivative $0$.`, key: 't', sol: r`True. $\dfrac{1}{\sqrt{1 - x^2}} - \dfrac{1}{\sqrt{1 - x^2}} = 0$; indeed the sum is the constant $\dfrac{\pi}{2}$.`, d: 1, c: 'understanding', t: [5] }), (C) => { C.assert([-0.5, 0, 0.7].every((x) => Math.abs(D((u) => As(u) + Ac(u), x)) < 1e-6), 'zero derivative'); C.key('t'); });
Q('tf4', mk.tf({ stem: r`The reciprocal function $\dfrac{1}{x - 3}$ has a removable discontinuity at $x = 3$.`, key: 'f', sol: r`False. As $x \to 3$ the values grow without bound ($-\infty$ on the left, $+\infty$ on the right): an infinite discontinuity, which no single value can repair.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(kind((x) => 1 / (x - 3), 3, NaN) === 'infinite', 'infinite'); C.key('f'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`The quotient $\dfrac{e^{2x} - 1}{x}$ is undefined at $0$. To remove this discontinuity, its value at $0$ should be defined as ___.`, acc: [['2', '$2$']], sol: r`$\dfrac{e^{2x} - 1}{x} = 2 \cdot \dfrac{e^{2x} - 1}{2x} \to 2 \cdot 1 = 2$.`, d: 2, c: 'understanding', t: [2] }), (C) => C.blank(Math.round(lim((x) => (E(2 * x) - 1) / x, 0, 1) * 1e4) / 1e4));
Q('fb2', mk.fill({ stem: r`If $y = e^{\sin 2x}$, the slope $\dfrac{dy}{dx}$ at $x = 0$ equals ___.`, acc: [['2', '$2$']], sol: r`$\dfrac{dy}{dx} = e^{\sin 2x} \cdot 2\cos 2x$, which is $1 \cdot 2 = 2$ at $x = 0$.`, d: 2, c: 'understanding', t: [4] }), (C) => C.blank(Math.round(D((x) => E(S(2 * x)), 0) * 1e6) / 1e6));
Q('fb3', mk.fill({ stem: r`For $y = \log(x^2 + 1)$, the derivative at $x = 1$ is ___.`, acc: [['1', '$1$']], sol: r`$\dfrac{dy}{dx} = \dfrac{2x}{x^2 + 1}$, which is $\dfrac{2}{2} = 1$ at $x = 1$.`, d: 1, c: 'understanding', t: [4] }), (C) => C.blank(Math.round(D((x) => L(x * x + 1), 1) * 1e6) / 1e6));
Q('fb4', mk.fill({ stem: r`The step function $f(x) = [2x]$ is discontinuous at exactly ___ points of the open interval $(0, 2)$.`, acc: [['3', '$3$', 'three']], sol: r`$[2x]$ jumps whenever $2x$ is an integer, that is at $x = \dfrac12, 1, \dfrac32$ inside the interval: $3$ points.`, d: 2, c: 'application', t: [1, 2] }), (C) => { const g = (x) => fl(2 * x); let n = 0; for (let k = 1; k < 200; k++) { const a = k / 100; if (kind(g, a, g(a)) !== 'continuous') n++; } C.blank(n); });

// =============================================================== numerical
Q('n01', mk.num({ stem: r`A cosine quotient is completed at the origin: $f(x) = \dfrac{1 - \cos 6x}{x^2}$ for $x \ne 0$ and $f(0) = k$. Find $k$ for continuity at $0$.`, value: 18, sol: r`$1 - \cos 6x = 2\sin^2 3x$, so $f(x) = 18\left(\dfrac{\sin 3x}{3x}\right)^2 \to 18$. Hence $k = 18$.`, scheme: [[r`Half-angle form and $k = 18$`, 1]], d: 3, c: 'application', t: [1], time: 90 }), (C) => { const g = (x) => (1 - Co(6 * x)) / (x * x); C.assert(Math.abs(g(1e-3) - 18) < 1e-3 && Math.abs(g(-1e-3) - 18) < 1e-3, 'limit 18'); C.val(18); });
Q('n02', mk.num({ stem: r`Rationalise to find the value $a$ that makes $f(x) = \dfrac{\sqrt{x + 4} - 2}{x}$ ($x \ne 0$), $f(0) = a$, continuous at the origin.`, value: 0.25, sol: r`Multiply by $\sqrt{x + 4} + 2$: $f(x) = \dfrac{1}{\sqrt{x + 4} + 2} \to \dfrac{1}{4} = 0.25$. So $a = 0.25$.`, scheme: [[r`Rationalised; $a = 0.25$`, 1]], d: 2, c: 'application', t: [1], time: 75 }), (C) => C.val(lim((x) => (sq(x + 4) - 2) / x, 0, 1), 1e-5));
Q('n03', mk.num({ stem: r`A fifth power of a quadratic, $f(x) = (2x^2 - 3)^5$, is differentiated. Find $f'(1)$.`, value: 20, sol: r`$f'(x) = 5(2x^2 - 3)^4 \cdot 4x$. At $x = 1$: $5 \times 1 \times 4 = 20$.`, scheme: [[r`Chain rule and value $20$`, 1]], d: 2, c: 'understanding', t: [4], time: 60 }), (C) => C.val(D((x) => (2 * x * x - 3) ** 5, 1), 1e-4));
Q('n04', mk.num({ stem: r`Find the slope of $y = \tan^{-1}(3x)$ where it crosses the origin.`, value: 3, sol: r`$\dfrac{dy}{dx} = \dfrac{3}{1 + 9x^2}$, which equals $3$ at $x = 0$.`, scheme: [[r`$\dfrac{3}{1 + 9x^2}$ and $3$`, 1]], d: 1, c: 'understanding', t: [5], time: 45 }), (C) => C.val(D((x) => At(3 * x), 0), 1e-6));
Q('n05', mk.num({ stem: r`The function $2^x$ is differentiated at $x = 0$. Give the value correct to three decimal places.`, value: 0.693, tol: 0.001, sol: r`$\dfrac{d}{dx}2^x = 2^x\log 2$, so at $x = 0$ the value is $\log 2 \approx 0.693$.`, scheme: [[r`$2^x\log 2$, then $0.693$`, 1]], d: 2, c: 'understanding', t: [4], time: 60 }), (C) => C.val(D((x) => 2 ** x, 0), 0.001));
Q('n06', mk.num({ stem: r`A "distance to two posts" function is $f(x) = |x - 1| + |x - 3|$. At how many real points is it **not** differentiable?`, value: 2, sol: r`Corners can occur only where an absolute value changes sign: $x = 1$ (slopes $-2$ and $0$) and $x = 3$ (slopes $0$ and $2$). Elsewhere $f$ is linear. So $2$ points.`, scheme: [[r`Corners at $1$ and $3$: $2$ points`, 1]], d: 3, c: 'application', t: [3], time: 75 }), (C) => { const f = (x) => ab(x - 1) + ab(x - 3); let n = 0; for (let k = -300; k <= 700; k++) { const a = k / 100; if (!close(LHD(f, a), RHD(f, a), 1e-3)) n++; } C.val(n); });

// =============================================================== short answer (2 marks)
Q('s201', mk.short({ marks: 2, stem: r`A three-part rule is $f(x) = \begin{cases} 3x - 2, & x < 2 \\ 4, & x = 2 \\ x^2, & x > 2 \end{cases}$. Test whether it is continuous at $x = 2$.`, model: r`Left-hand limit: $3(2) - 2 = 4$. Right-hand limit: $2^2 = 4$. Value: $f(2) = 4$. All three agree, so $f$ is **continuous** at $x = 2$.`, sol: 'Compare both one-sided limits with the value.', scheme: [['Both one-sided limits found', 1], ['Compared with $f(2) = 4$: continuous', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { const g = (x) => (x < 2 ? 3 * x - 2 : x === 2 ? 4 : x * x); C.assert(isCont(g, 2, 4), 'continuous'); C.model([4, 'continuous']); });
Q('s202', mk.short({ marks: 2, stem: r`A rule is recorded as $f(x) = \begin{cases} x^2, & x < 1 \\ 2, & x = 1 \\ 2x - 1, & x > 1 \end{cases}$. Classify the discontinuity at $x = 1$ and say how to remove it if possible.`, model: r`Left-hand limit $1^2 = 1$; right-hand limit $2(1) - 1 = 1$. The limit exists and equals $1$, but $f(1) = 2$. So the discontinuity is **removable**: redefine $f(1) = 1$.`, sol: 'Equal one-sided limits with a different value means removable.', scheme: [['Both limits equal $1$, value $2$', 1], ['Removable; redefine $f(1) = 1$', 1]], d: 2, c: 'application', t: [2], time: 90 }), (C) => { const g = (x) => (x < 1 ? x * x : x === 1 ? 2 : 2 * x - 1); C.assert(kind(g, 1, 2) === 'removable' && close(lim(g, 1, 1), 1, 1e-4), 'removable, limit 1'); C.model([1, 'removable']); });
Q('s203', mk.short({ marks: 2, stem: r`Find $k$ if the sine quotient $f(x) = \dfrac{\sin kx}{3x}$ for $x \ne 0$, with $f(0) = 2$, is continuous at the origin.`, model: r`$\dfrac{\sin kx}{3x} = \dfrac{k}{3} \cdot \dfrac{\sin kx}{kx} \to \dfrac{k}{3}$. Continuity needs $\dfrac{k}{3} = 2$, so $k = 6$.`, sol: r`Use $\dfrac{\sin u}{u} \to 1$.`, scheme: [[r`Limit $\dfrac{k}{3}$`, 1], ['$k = 6$', 1]], d: 2, c: 'application', t: [1], time: 90 }), (C) => { const k = 6; C.assert(isCont((x) => (x === 0 ? 2 : S(k * x) / (3 * x)), 0, 2), 'k = 6'); C.model([6]); });
Q('s204', mk.short({ marks: 2, stem: r`Show that the V-shaped function $g(x) = |2x - 3|$ is not differentiable at $x = \dfrac{3}{2}$.`, model: r`$g\left(\dfrac32\right) = 0$. For $h > 0$: $\dfrac{|2h| - 0}{h} = 2$, so the right-hand derivative is $2$. For $h < 0$: $\dfrac{|2h|}{h} = -2$, so the left-hand derivative is $-2$. Since $-2 \ne 2$, $g$ is **not differentiable** at $\dfrac32$.`, sol: 'One-sided difference quotients at the tip.', scheme: [['Right-hand derivative $2$ and left-hand derivative $-2$', 1], ['Unequal, so not differentiable', 1]], d: 2, c: 'application', t: [3], time: 90 }), (C) => { const g = (x) => ab(2 * x - 3); C.assert(close(LHD(g, 1.5), -2, 1e-4) && close(RHD(g, 1.5), 2, 1e-4), '-2, 2'); C.model([2, 'not differentiable']); });
Q('s205', mk.short({ marks: 2, stem: r`Differentiate $\log\left(\tan\dfrac{x}{2}\right)$ with respect to $x$ for $0 < x < \pi$, and simplify.`, model: r`$\dfrac{1}{\tan\frac{x}{2}} \cdot \sec^2\dfrac{x}{2} \cdot \dfrac12 = \dfrac{\cos\frac{x}{2}}{\sin\frac{x}{2}} \cdot \dfrac{1}{2\cos^2\frac{x}{2}} = \dfrac{1}{2\sin\frac{x}{2}\cos\frac{x}{2}} = \dfrac{1}{\sin x} = \operatorname{cosec} x$.`, sol: 'Chain rule through log, tan and x/2, then the double-angle identity.', scheme: [['Chain rule with all three factors', 1], [r`Simplified to $\operatorname{cosec} x$`, 1]], d: 3, c: 'application', t: [4], time: 120 }), (C) => { C.assert(sameD((x) => L(T(x / 2)), (x) => 1 / S(x), [0.4, 1.3, 2.6]), 'cosec x'); C.model([r`\operatorname{cosec} x`]); });
Q('s206', mk.short({ marks: 2, stem: r`Differentiate the cube $\cos^3 4x$ with respect to $x$.`, model: r`$\dfrac{d}{dx}\cos^3 4x = 3\cos^2 4x \cdot (-\sin 4x) \cdot 4 = -12\cos^2 4x\sin 4x$.`, sol: 'Power, then cosine, then 4x.', scheme: [['Power and cosine factors', 1], [r`$-12\cos^2 4x\sin 4x$`, 1]], d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { C.assert(sameD((x) => Co(4 * x) ** 3, (x) => -12 * Co(4 * x) ** 2 * S(4 * x), [0.1, 0.5, 1.2]), 'derivative'); C.model([r`-12\cos^2 4x\sin 4x`]); });
Q('s207', mk.short({ marks: 2, stem: r`For $x < 0$, find the derivative of the composite angle $\sin^{-1}(e^x)$.`, model: r`$\dfrac{d}{dx}\sin^{-1}(e^x) = \dfrac{1}{\sqrt{1 - (e^x)^2}} \cdot e^x = \dfrac{e^x}{\sqrt{1 - e^{2x}}}$, valid since $0 < e^x < 1$ for $x < 0$.`, sol: 'Inverse sine derivative with the chain rule.', scheme: [['Inverse sine derivative', 1], [r`$\dfrac{e^x}{\sqrt{1 - e^{2x}}}$`, 1]], d: 2, c: 'understanding', t: [5], time: 75 }), (C) => { C.assert(sameD((x) => As(E(x)), (x) => E(x) / sq(1 - E(2 * x)), [-2, -0.8, -0.1]), 'derivative'); C.model([r`\dfrac{e^x}{\sqrt{1 - e^{2x}}}`]); });
Q('s208', mk.short({ marks: 2, stem: r`Use $x = \tan\theta$ to simplify $\tan^{-1}\left(\dfrac{1 + x}{1 - x}\right)$ for $x < 1$, and hence differentiate it.`, model: r`$\dfrac{1 + \tan\theta}{1 - \tan\theta} = \tan\left(\dfrac{\pi}{4} + \theta\right)$, and for $x < 1$, $-\dfrac{\pi}{4} < \dfrac{\pi}{4} + \theta < \dfrac{\pi}{2}$. So the function is $\dfrac{\pi}{4} + \tan^{-1} x$, with derivative $\dfrac{1}{1 + x^2}$.`, sol: 'Write the fraction as tan of a sum, check the angle lies in the principal range.', scheme: [[r`$\tan\left(\dfrac{\pi}{4} + \theta\right)$ and range`, 1], [r`Derivative $\dfrac{1}{1 + x^2}$`, 1]], d: 3, c: 'application', t: [5], time: 120 }), (C) => { C.assert(sameD((x) => At((1 + x) / (1 - x)), (x) => 1 / (1 + x * x), [-3, -0.4, 0.6]), 'derivative'); C.model([r`\dfrac{1}{1 + x^2}`]); });
Q('s209', mk.short({ marks: 2, stem: r`A damped signal is $s(x) = e^{-x}\cos x$. Find $\dfrac{ds}{dx}$.`, model: r`Product rule: $\dfrac{ds}{dx} = -e^{-x}\cos x + e^{-x}(-\sin x) = -e^{-x}(\cos x + \sin x)$.`, sol: 'Product rule with the chain rule on the exponential.', scheme: [['Product rule set up', 1], [r`$-e^{-x}(\cos x + \sin x)$`, 1]], d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { C.assert(sameD((x) => E(-x) * Co(x), (x) => -E(-x) * (Co(x) + S(x)), [0, 0.9, 2]), 'derivative'); C.model([r`-e^{-x}(\cos x + \sin x)`]); });
Q('s210', mk.short({ marks: 2, stem: r`Explain, using the algebra of continuous functions, why $r(x) = \dfrac{x^2 + 1}{x^2 - 9}$ is continuous at every real number except $\pm 3$.`, model: r`The numerator and denominator are polynomials, which are continuous everywhere. A quotient of continuous functions is continuous wherever the denominator is non-zero. Here $x^2 - 9 = 0$ only at $x = 3$ and $x = -3$, where $r$ is not defined. So $r$ is continuous at every other real number.`, sol: 'Polynomials are continuous; quotients fail only at zeros of the denominator.', scheme: [['Polynomials continuous; quotient rule for continuity', 1], ['Only the zeros $\\pm 3$ excluded', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { const g = (x) => (x * x + 1) / (x * x - 9); C.assert([-2, 0, 1.5, 4].every((a) => isCont(g, a, g(a))) && kind(g, 3, NaN) === 'infinite', 'continuous except at 3'); C.model([3, '-3']); });

// =============================================================== short answer (3 marks)
Q('s301', mk.short({ marks: 3, stem: r`Determine the constants $a$ and $b$ for which the three-piece function $f(x) = \begin{cases} 3, & x \le -1 \\ ax + b, & -1 < x < 3 \\ 11, & x \ge 3 \end{cases}$ has no break anywhere on the real line.`, model: r`Each piece is continuous, so only the joins $x = -1$ and $x = 3$ matter. At $x = -1$: $-a + b = 3$. At $x = 3$: $3a + b = 11$. Subtracting, $4a = 8$, so $a = 2$ and $b = 5$.`, sol: 'Equate one-sided limits at both joins.', scheme: [['$-a + b = 3$', 1], ['$3a + b = 11$', 1], ['$a = 2$, $b = 5$', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => { const a = 2, b = 5; const g = (x) => (x <= -1 ? 3 : x < 3 ? a * x + b : 11); C.assert(isCont(g, -1, 3) && isCont(g, 3, 11), 'continuous at -1 and 3'); C.model([2, 5]); });
Q('s302', mk.short({ marks: 3, stem: r`For $f(x) = |x| + |x - 2|$, show that $f$ is continuous at $x = 2$ but not differentiable there.`, model: r`$f(2) = 2$. Near $x = 2$ with $x > 0$: for $0 < x < 2$, $f(x) = x + (2 - x) = 2$; for $x > 2$, $f(x) = 2x - 2$. Both one-sided limits are $2 = f(2)$, so $f$ is continuous at $2$. The left-hand derivative is $0$ (constant piece) and the right-hand derivative is $2$; they differ, so $f$ is **not differentiable** at $x = 2$.`, sol: 'Write f without absolute values on each side of 2.', scheme: [['Pieces on each side of $2$', 1], ['Continuity at $2$', 1], ['Slopes $0$ and $2$: not differentiable', 1]], d: 3, c: 'analysis', t: [1, 3], time: 150 }), (C) => { const f = (x) => ab(x) + ab(x - 2); C.assert(isCont(f, 2, 2) && Math.abs(LHD(f, 2)) < 1e-4 && close(RHD(f, 2), 2, 1e-4), 'slopes 0 and 2'); C.model([0, 2, 'not differentiable']); });
Q('s303', mk.short({ marks: 3, stem: r`On $[0, 2)$ consider $f(x) = x[x]$, where $[x]$ is the greatest integer function. Examine the continuity and differentiability of $f$ at $x = 1$.`, model: r`For $0 \le x < 1$, $[x] = 0$, so $f(x) = 0$; for $1 \le x < 2$, $[x] = 1$, so $f(x) = x$. Left-hand limit at $1$: $0$. Right-hand limit and value: $f(1) = 1$. Since $0 \ne 1$, $f$ is **not continuous** at $1$ (a jump), and therefore **not differentiable** there.`, sol: 'Rewrite f piece by piece using the value of [x].', scheme: [['Pieces $0$ and $x$', 1], ['Limits $0$ and $1$: not continuous', 1], ['Hence not differentiable', 1]], d: 3, c: 'analysis', t: [2, 3], time: 150 }), (C) => { const f = (x) => x * fl(x); C.assert(kind(f, 1, f(1)) === 'jump' && Math.abs(lim(f, 1, -1)) < 1e-6 && f(1) === 1, 'jump 0 to 1'); C.model([0, 1, 'not continuous', 'not differentiable']); });
Q('s304', mk.short({ marks: 3, stem: r`An imagined spreadsheet formula gives $f(x) = \dfrac{x^2 - 3x - 10}{x + 2}$ for $x \ne -2$ and returns $f(-2) = 1$. Classify the discontinuity at $x = -2$ and redefine $f(-2)$ to make $f$ continuous.`, model: r`$x^2 - 3x - 10 = (x - 5)(x + 2)$, so for $x \ne -2$, $f(x) = x - 5 \to -7$ from both sides. The limit exists but $f(-2) = 1 \ne -7$: a **removable** discontinuity. Redefining $f(-2) = -7$ makes $f$ continuous at $-2$.`, sol: 'Factorise, cancel, take the limit, compare with the stored value.', scheme: [['Factorised; limit $-7$', 1], ['Removable, since the limit exists', 1], ['Redefine $f(-2) = -7$', 1]], d: 3, c: 'application', t: [2], time: 150 }), (C) => { const g = (x) => (x === -2 ? 1 : (x * x - 3 * x - 10) / (x + 2)); C.assert(kind(g, -2, 1) === 'removable' && close(lim(g, -2, 1), -7, 1e-4), 'removable, limit -7'); C.model([-7, 'removable']); });
Q('s305', mk.short({ marks: 3, stem: r`Find $a$ and $b$ so that $f(x) = \begin{cases} ax^2 + b, & x < 1 \\ 4x - 1, & x \ge 1 \end{cases}$ is differentiable at $x = 1$.`, model: r`Differentiability needs continuity: $a + b = 4 - 1 = 3$. It also needs equal one-sided derivatives: $2a(1) = 4$, so $a = 2$. Then $b = 1$. With $a = 2$, $b = 1$ both pieces give value $3$ and slope $4$ at $x = 1$.`, sol: 'Two conditions: matching values and matching slopes.', scheme: [['Continuity: $a + b = 3$', 1], ['Equal slopes: $2a = 4$', 1], ['$a = 2$, $b = 1$', 1]], d: 3, c: 'application', t: [3], time: 150 }), (C) => { const a = 2, b = 1; const g = (x) => (x < 1 ? a * x * x + b : 4 * x - 1); C.assert(isCont(g, 1, 3) && close(LHD(g, 1), RHD(g, 1), 1e-4), 'smooth join'); C.model([2, 1]); });
Q('s306', mk.short({ marks: 3, stem: r`Differentiate the root of a tangent, $\sqrt{\tan 3x}$, for $0 < x < \dfrac{\pi}{6}$.`, model: r`$\dfrac{d}{dx}\sqrt{\tan 3x} = \dfrac{1}{2\sqrt{\tan 3x}} \cdot \sec^2 3x \cdot 3 = \dfrac{3\sec^2 3x}{2\sqrt{\tan 3x}}$.`, sol: 'Root, then tangent, then 3x.', scheme: [['Derivative of the root', 1], ['Times $\\sec^2 3x$ and $3$', 1], [r`$\dfrac{3\sec^2 3x}{2\sqrt{\tan 3x}}$`, 1]], d: 3, c: 'understanding', t: [4], time: 120 }), (C) => { C.assert(sameD((x) => sq(T(3 * x)), (x) => (3 * sec(3 * x) ** 2) / (2 * sq(T(3 * x))), [0.1, 0.25, 0.45]), 'derivative'); C.model([r`\dfrac{3\sec^2 3x}{2\sqrt{\tan 3x}}`]); });
Q('s307', mk.short({ marks: 3, stem: r`A product of an exponential and an inverse sine, $e^x\sin^{-1} x$, is differentiated on $-1 < x < 1$. Find the derivative.`, model: r`Product rule: $\dfrac{d}{dx}\left(e^x\sin^{-1} x\right) = e^x\sin^{-1} x + e^x \cdot \dfrac{1}{\sqrt{1 - x^2}} = e^x\left(\sin^{-1} x + \dfrac{1}{\sqrt{1 - x^2}}\right)$.`, sol: 'Product rule with the standard inverse-sine derivative.', scheme: [['Product rule', 1], ['Derivative of the inverse sine', 1], ['Final form', 1]], d: 2, c: 'understanding', t: [4, 5], time: 120 }), (C) => { C.assert(sameD((x) => E(x) * As(x), (x) => E(x) * (As(x) + 1 / sq(1 - x * x)), [-0.6, 0.2, 0.7]), 'derivative'); C.model([r`\dfrac{1}{\sqrt{1 - x^2}}`]); });
Q('s308', mk.short({ marks: 3, stem: r`With the substitution $x = \sin\theta$, differentiate $\sin^{-1}\left(2x\sqrt{1 - x^2}\right)$ on $-\dfrac{1}{\sqrt{2}} < x < \dfrac{1}{\sqrt{2}}$.`, model: r`Let $x = \sin\theta$ with $-\dfrac{\pi}{4} < \theta < \dfrac{\pi}{4}$. Then $2x\sqrt{1 - x^2} = 2\sin\theta\cos\theta = \sin 2\theta$, and $-\dfrac{\pi}{2} < 2\theta < \dfrac{\pi}{2}$. So the function is $2\theta = 2\sin^{-1} x$, and its derivative is $\dfrac{2}{\sqrt{1 - x^2}}$.`, sol: 'Substitute, simplify with the double angle, check the principal range, differentiate.', scheme: [['Substitution and $\\sin 2\\theta$', 1], ['Range check: function $= 2\\sin^{-1} x$', 1], [r`$\dfrac{2}{\sqrt{1 - x^2}}$`, 1]], d: 4, c: 'analysis', t: [5], time: 180 }), (C) => { C.assert(sameD((x) => As(2 * x * sq(1 - x * x)), (x) => 2 / sq(1 - x * x), [-0.6, 0.1, 0.65]), 'derivative'); C.model([r`2\sin^{-1} x`, r`\dfrac{2}{\sqrt{1 - x^2}}`]); });
Q('s309', mk.short({ marks: 3, stem: r`For $0 < x < 1$, simplify $\cos^{-1}\left(\dfrac{1 - x^2}{1 + x^2}\right)$ by putting $x = \tan\theta$, and then find its derivative.`, model: r`With $x = \tan\theta$, $0 < \theta < \dfrac{\pi}{4}$: $\dfrac{1 - \tan^2\theta}{1 + \tan^2\theta} = \cos 2\theta$ and $0 < 2\theta < \dfrac{\pi}{2}$, inside $[0, \pi]$. So the function is $2\theta = 2\tan^{-1} x$, and its derivative is $\dfrac{2}{1 + x^2}$.`, sol: 'Substitute, use the cos 2θ identity, check the principal range.', scheme: [['$\\cos 2\\theta$ identity', 1], ['Range check: $2\\tan^{-1} x$', 1], [r`$\dfrac{2}{1 + x^2}$`, 1]], d: 3, c: 'application', t: [5], time: 150 }), (C) => { C.assert(sameD((x) => Ac((1 - x * x) / (1 + x * x)), (x) => 2 / (1 + x * x), [0.2, 0.5, 0.9]), 'derivative'); C.model([r`2\tan^{-1} x`, r`\dfrac{2}{1 + x^2}`]); });
Q('s310', mk.short({ marks: 3, stem: r`Show that the derivative of $\log\sqrt{\dfrac{1 + \sin x}{1 - \sin x}}$ on $-\dfrac{\pi}{2} < x < \dfrac{\pi}{2}$ is $\sec x$.`, model: r`The function is $\dfrac12\left[\log(1 + \sin x) - \log(1 - \sin x)\right]$. Differentiating: $\dfrac12\left[\dfrac{\cos x}{1 + \sin x} + \dfrac{\cos x}{1 - \sin x}\right] = \dfrac12 \cdot \dfrac{2\cos x}{1 - \sin^2 x} = \dfrac{\cos x}{\cos^2 x} = \sec x$.`, sol: 'Use log laws first, then differentiate each logarithm.', scheme: [['Log laws applied', 1], ['Both logarithms differentiated', 1], ['Combined to $\\sec x$', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { C.assert(sameD((x) => L(sq((1 + S(x)) / (1 - S(x)))), sec, [-1.1, 0.2, 1.3]), 'sec x'); C.model([r`\sec x`]); });

// =============================================================== long answer (5 marks, in parts)
Q('l01', mk.long({ stem: r`A rule is defined by $f(x) = \begin{cases} kx^2, & x \le 2 \\ 3x + 4, & x > 2 \end{cases}$.

(a) Find $k$ so that $f$ is continuous at $x = 2$. [2]

(b) With this $k$, find both one-sided derivatives at $x = 2$ and decide whether $f$ is differentiable there. [3]`, model: r`(a) Left-hand limit and value: $4k$. Right-hand limit: $3(2) + 4 = 10$. So $4k = 10$ and $k = \dfrac{5}{2}$.

(b) Left-hand derivative: $\lim_{h \to 0^-}\dfrac{\frac52(2 + h)^2 - 10}{h} = \lim_{h \to 0^-}\dfrac{10h + \frac52h^2}{h} = 10$. Right-hand derivative: $\lim_{h \to 0^+}\dfrac{3(2 + h) + 4 - 10}{h} = 3$. Since $10 \ne 3$, $f$ is continuous but **not differentiable** at $x = 2$.`, sol: 'Continuity fixes k; then compare the one-sided difference quotients.', scheme: [['(a) $4k = 10$', 1], [r`(a) $k = \dfrac{5}{2}$`, 1], ['(b) Left-hand derivative $10$', 1], ['(b) Right-hand derivative $3$', 1], ['(b) Not differentiable', 1]], d: 3, c: 'application', t: [1, 3], time: 360 }), (C) => { const k = 10 / 4; const g = (x) => (x <= 2 ? k * x * x : 3 * x + 4); C.assert(isCont(g, 2, 10), 'continuous'); C.assert(close(LHD(g, 2), 10, 1e-4) && close(RHD(g, 2), 3, 1e-4), 'slopes 10 and 3'); C.model([r`\dfrac{5}{2}`, 10, 3, 'not differentiable']); });

Q('l02', mk.long({ stem: r`Consider $f(x) = \dfrac{x^2 - 1}{x^2 - 3x + 2}$.

(a) Find the points where $f$ is discontinuous and classify each discontinuity. [3]

(b) Redefine $f$ at the removable point so that it becomes continuous there, and explain why the other discontinuity cannot be removed. [2]`, model: r`(a) $x^2 - 3x + 2 = (x - 1)(x - 2)$, so $f$ is undefined, hence discontinuous, at $x = 1$ and $x = 2$. For $x \ne 1, 2$: $f(x) = \dfrac{(x - 1)(x + 1)}{(x - 1)(x - 2)} = \dfrac{x + 1}{x - 2}$.
At $x = 1$: the limit is $\dfrac{2}{-1} = -2$, which exists: a **removable** discontinuity.
At $x = 2$: the denominator tends to $0$ while the numerator tends to $3$, so $|f(x)| \to \infty$: an **infinite** discontinuity.

(b) Define $f(1) = -2$; then the limit and the value agree. At $x = 2$ no finite limit exists, so no choice of $f(2)$ can make $f$ continuous there.`, sol: 'Factorise both quadratics, cancel the common factor, and examine each zero of the denominator.', scheme: [['(a) Points $1$ and $2$', 1], ['(a) Removable at $1$, limit $-2$', 1], ['(a) Infinite at $2$', 1], ['(b) Define $f(1) = -2$', 1], ['(b) Reason for $x = 2$', 1]], d: 4, c: 'analysis', t: [1, 2], time: 420 }), (C) => { const f = (x) => (x * x - 1) / (x * x - 3 * x + 2); C.assert(kind(f, 1, NaN) === 'removable' && close(lim(f, 1, 1), -2, 1e-4), 'removable at 1, limit -2'); C.assert(kind(f, 2, NaN) === 'infinite', 'infinite at 2'); C.model([-2, 'removable', 'infinite']); });

Q('l03', mk.long({ stem: r`Let $f(x) = |x - 1| + |x + 2|$.

(a) Write $f$ without absolute-value signs on the intervals $x < -2$, $-2 \le x \le 1$ and $x > 1$. [2]

(b) Show that $f$ is continuous at $x = 1$ and at $x = -2$, and find the one-sided derivatives at both points. State where $f$ is not differentiable. [3]`, model: r`(a) For $x < -2$: $f(x) = (1 - x) + (-x - 2) = -2x - 1$. For $-2 \le x \le 1$: $f(x) = (1 - x) + (x + 2) = 3$. For $x > 1$: $f(x) = (x - 1) + (x + 2) = 2x + 1$.

(b) At $x = -2$: $-2(-2) - 1 = 3 = f(-2)$, so continuous; slopes $-2$ (left) and $0$ (right). At $x = 1$: $2(1) + 1 = 3 = f(1)$, so continuous; slopes $0$ (left) and $2$ (right). The one-sided derivatives differ at both points, so $f$ is **not differentiable at $x = -2$ and $x = 1$**, and differentiable everywhere else.`, sol: 'Remove the absolute values interval by interval, then compare values and slopes at the joins.', scheme: [['(a) Three pieces', 2], ['(b) Continuity at both points', 1], ['(b) One-sided derivatives', 1], ['(b) Not differentiable at $-2$ and $1$', 1]], d: 3, c: 'analysis', t: [1, 3], time: 420 }), (C) => { const f = (x) => ab(x - 1) + ab(x + 2); C.assert(isCont(f, -2, 3) && isCont(f, 1, 3), 'continuous'); C.assert(close(LHD(f, -2), -2, 1e-4) && Math.abs(RHD(f, -2)) < 1e-4 && Math.abs(LHD(f, 1)) < 1e-4 && close(RHD(f, 1), 2, 1e-4), 'slopes'); C.model([-2, 0, 2, '2x + 1', '-2x - 1']); });

Q('l04', mk.long({ stem: r`Inverse trigonometric derivatives by substitution.

(a) For $-\dfrac{1}{\sqrt{3}} < x < \dfrac{1}{\sqrt{3}}$, differentiate $\tan^{-1}\left(\dfrac{3x - x^3}{1 - 3x^2}\right)$. [2]

(b) For $x < 0$, differentiate $\sin^{-1}\left(\dfrac{2^{x + 1}}{1 + 4^x}\right)$. [3]`, model: r`(a) Put $x = \tan\theta$, $-\dfrac{\pi}{6} < \theta < \dfrac{\pi}{6}$: $\dfrac{3\tan\theta - \tan^3\theta}{1 - 3\tan^2\theta} = \tan 3\theta$ with $-\dfrac{\pi}{2} < 3\theta < \dfrac{\pi}{2}$. So the function is $3\theta = 3\tan^{-1} x$ and its derivative is $\dfrac{3}{1 + x^2}$.

(b) Put $2^x = \tan\theta$; for $x < 0$, $0 < \tan\theta < 1$, so $0 < \theta < \dfrac{\pi}{4}$. Then $\dfrac{2^{x + 1}}{1 + 4^x} = \dfrac{2\tan\theta}{1 + \tan^2\theta} = \sin 2\theta$ with $0 < 2\theta < \dfrac{\pi}{2}$. So the function is $2\theta = 2\tan^{-1}(2^x)$, and its derivative is $\dfrac{2 \cdot 2^x\log 2}{1 + 4^x}$.`, sol: 'Choose the substitution that turns the fraction into a multiple-angle formula, and check the angle stays in the principal range.', scheme: [['(a) $\\tan 3\\theta$ with range check', 1], [r`(a) $\dfrac{3}{1 + x^2}$`, 1], ['(b) Substitution $2^x = \\tan\\theta$ and range', 1], ['(b) Function $= 2\\tan^{-1}(2^x)$', 1], [r`(b) $\dfrac{2^{x + 1}\log 2}{1 + 4^x}$`, 1]], d: 4, c: 'analysis', t: [4, 5], time: 480 }), (C) => { C.assert(sameD((x) => At((3 * x - x ** 3) / (1 - 3 * x * x)), (x) => 3 / (1 + x * x), [-0.5, 0.1, 0.55]), '(a)'); C.assert(sameD((x) => As(2 ** (x + 1) / (1 + 4 ** x)), (x) => (2 * 2 ** x * L(2)) / (1 + 4 ** x), [-3, -1, -0.2]), '(b)'); C.model([r`\dfrac{3}{1 + x^2}`, r`2\tan^{-1}(2^x)`, r`\dfrac{2 \cdot 2^x\log 2}{1 + 4^x}`]); });

Q('l05', mk.long({ stem: r`An imagined auto-rickshaw tariff in Guwahati charges $F(d) = 40 + 12d$ rupees for a ride of $d$ km when $0 \le d \le 5$, and $F(d) = a + 15d$ rupees when $d > 5$.

(a) Find $a$ so that the fare has no sudden jump at $d = 5$. [2]

(b) With this $a$, is $F$ differentiable at $d = 5$? Find the one-sided rates and interpret your answer for a passenger. [3]`, model: r`(a) Left-hand limit and value: $40 + 12(5) = 100$. Right-hand limit: $a + 75$. No jump needs $a + 75 = 100$, so $a = 25$.

(b) For $d < 5$ the fare rises at ₹$12$ per km; for $d > 5$ at ₹$15$ per km. The left-hand derivative at $5$ is $12$ and the right-hand derivative is $15$. They differ, so $F$ is continuous but **not differentiable** at $d = 5$: the fare has no jump there, but each extra kilometre beyond $5$ km costs ₹$3$ more than before.`, sol: 'Continuity fixes a; the two per-km rates are the one-sided derivatives.', scheme: [['(a) $a + 75 = 100$', 1], ['(a) $a = 25$', 1], ['(b) Left-hand rate $12$', 1], ['(b) Right-hand rate $15$', 1], ['(b) Not differentiable, with interpretation', 1]], d: 3, c: 'application', t: [1, 3], time: 360 }), (C) => { const a = 100 - 75; const F = (d) => (d <= 5 ? 40 + 12 * d : a + 15 * d); C.assert(isCont(F, 5, 100), 'no jump'); C.assert(close(LHD(F, 5), 12, 1e-4) && close(RHD(F, 5), 15, 1e-4), 'rates'); C.model([25, 12, 15, 'not differentiable']); });

Q('l06', mk.long({ stem: r`Simplify first, then differentiate.

(a) Differentiate $\dfrac{\sin x}{1 + \cos x}$ for $-\pi < x < \pi$, giving the answer in terms of $\dfrac{x}{2}$. [2]

(b) Show that $\sin^{-1}\left(\dfrac{x}{\sqrt{1 + x^2}}\right) = \tan^{-1} x$ for all real $x$, and hence find its derivative. [3]`, model: r`(a) $\dfrac{\sin x}{1 + \cos x} = \dfrac{2\sin\frac{x}{2}\cos\frac{x}{2}}{2\cos^2\frac{x}{2}} = \tan\dfrac{x}{2}$, so its derivative is $\dfrac12\sec^2\dfrac{x}{2}$.

(b) Put $x = \tan\theta$ with $-\dfrac{\pi}{2} < \theta < \dfrac{\pi}{2}$. Then $\sqrt{1 + x^2} = \sec\theta$ (positive in this range) and $\dfrac{x}{\sqrt{1 + x^2}} = \dfrac{\tan\theta}{\sec\theta} = \sin\theta$. Since $\theta$ lies in the principal range of $\sin^{-1}$, the function equals $\theta = \tan^{-1} x$. Its derivative is $\dfrac{1}{1 + x^2}$.`, sol: 'Half-angle identities in (a); a tangent substitution in (b).', scheme: [[r`(a) Simplified to $\tan\dfrac{x}{2}$`, 1], [r`(a) $\dfrac12\sec^2\dfrac{x}{2}$`, 1], ['(b) Substitution and $\\sec\\theta > 0$', 1], ['(b) Equals $\\tan^{-1} x$', 1], [r`(b) $\dfrac{1}{1 + x^2}$`, 1]], d: 3, c: 'application', t: [4, 5], time: 360 }), (C) => { C.assert(sameD((x) => S(x) / (1 + Co(x)), (x) => 0.5 / Co(x / 2) ** 2, [-2, 0.3, 2.5]), '(a)'); C.assert([-3, -0.4, 0.8, 5].every((x) => close(As(x / sq(1 + x * x)), At(x))) && sameD((x) => As(x / sq(1 + x * x)), (x) => 1 / (1 + x * x), [-2, 0.5, 3]), '(b)'); C.model([r`\tan\dfrac{x}{2}`, r`\dfrac{1}{1 + x^2}`]); });
